package com.codepathacademy.learning;
import java.util.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/learning-data/imports") public class LearningDataImportController {private final LearningDataImportService service;public LearningDataImportController(LearningDataImportService service){this.service=service;}@PostMapping("/preview") LearningDataImportService.Result preview(@AuthenticationPrincipal String userId,@RequestBody LearningDataImportService.Payload payload){return service.preview(userId,payload);}@PostMapping LearningDataImportService.ImportedResult importData(@AuthenticationPrincipal String userId,@RequestHeader("Idempotency-Key") String key,@RequestBody LearningDataImportService.Payload payload){return service.importData(userId,key,payload);}@GetMapping("/{id}") LearningDataImportService.ImportedResult get(@AuthenticationPrincipal String userId,@PathVariable UUID id){return service.get(userId,id);}@PostMapping("/{id}/conflicts/{sourceKey}/resolve") LearningDataImportService.ResolutionResult resolve(@AuthenticationPrincipal String userId,@PathVariable UUID id,@PathVariable String sourceKey,@RequestBody LearningDataImportService.ResolutionRequest request){return service.resolve(userId,id,sourceKey,request);}}
